<?php
declare(strict_types=1);
require_once __DIR__.'/StaySchema.php';
final class CashReport
{
    private const MAX=9007199254740991;
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function money(mixed $v):int{if(!is_int($v)&&(!is_string($v)||!preg_match('/^[0-9]+$/D',$v)))throw new HttpError(409,'Sổ tiền có dữ liệu không hợp lệ.');if($v<0||strlen((string)$v)>16||(strlen((string)$v)===16&&strcmp((string)$v,(string)self::MAX)>0))throw new HttpError(409,'Số tiền vượt phạm vi báo cáo.');return (int)$v;}
    private static function plus(int $a,int $b):int{if($b>self::MAX-$a)throw new HttpError(409,'Tổng tiền vượt phạm vi báo cáo.');return $a+$b;}
    private static function filters(array $in):array
    {
        if(array_diff(array_keys($in),['from','to','kind','method','direction','q','page']))throw new HttpError(400,'Bộ lọc thu hoàn không hợp lệ.');$out=['from'=>StaySchema::date($in['from']??null),'to'=>StaySchema::date($in['to']??null)];foreach(['kind'=>['ALL','ORDER','CART','BUNDLE','HOTEL','PARTNER','RIDE'],'method'=>['ALL','CASH','BANK','GATEWAY','UNSPECIFIED'],'direction'=>['ALL','IN','OUT']] as $key=>$allowed){$v=array_key_exists($key,$in)?$in[$key]:'ALL';if(!in_array($v,$allowed,true))throw new HttpError(400,'Bộ lọc thu hoàn không hợp lệ.');$out[$key]=$v;}
        $q=array_key_exists('q',$in)?$in['q']:'';if(!is_string($q)||str_contains($q,"\0")||mb_strlen($q,'UTF-8')>120)throw new HttpError(400,'Từ khóa tối đa 120 ký tự.');$out['q']=trim($q);$page=$in['page']??'1';if(array_key_exists('page',$in)&&!is_int($in['page'])&&!is_string($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)$page)||(int)$page>100000)throw new HttpError(400,'Trang không hợp lệ.');$out['page']=(int)$page;
        $days=(int)(new DateTimeImmutable($out['from']))->diff(new DateTimeImmutable($out['to']))->format('%r%a');if($days<0||$days>366)throw new HttpError(400,'Báo cáo tối đa 367 ngày.');return $out;
    }
    private static function zero():array{return ['received'=>0,'refunded'=>0,'net'=>0,'receiptCount'=>0,'refundCount'=>0];}
    private static function record(array &$summary,string $direction,int $amount):void{$key=$direction==='IN'?'received':'refunded';$count=$direction==='IN'?'receiptCount':'refundCount';$summary[$key]=self::plus($summary[$key],$amount);$summary[$count]++;$summary['net']=$summary['received']-$summary['refunded'];}
    public function build(array $input,bool $fullLedger=false):array
    {
        $f=self::filters($input);$zone=new DateTimeZone('Asia/Ho_Chi_Minh');$utc=new DateTimeZone('UTC');$start=(new DateTimeImmutable($f['from'].' 00:00:00',$zone))->setTimezone($utc)->format('Y-m-d H:i:s');$end=(new DateTimeImmutable($f['to'].' 00:00:00',$zone))->modify('+1 day')->setTimezone($utc)->format('Y-m-d H:i:s');
        // One row per receipt reference, never sum both reference and order payment as separate receipts.
        $receipt="SELECT CONCAT('IN:',r.reference_hash) AS id,CASE WHEN r.kind='ORDER_PAYMENT' THEN CASE WHEN cm.cart_id IS NOT NULL THEN 'CART' ELSE 'ORDER' END WHEN r.kind='HOTEL_PAYMENT' THEN 'HOTEL' ELSE 'PARTNER' END AS kind,COALESCE(cm.cart_id,r.entity_id) AS entityId,COALESCE(c.code,o.code,h.code,CONCAT('CTV:',r.entity_id)) AS code,'IN' AS direction,DATE(DATE_ADD(r.created_at,INTERVAL 7 HOUR)) AS effectiveDate,r.created_at AS recordedAt,CASE WHEN r.kind='PARTNER_REPAYMENT' THEN 'UNSPECIFIED' WHEN r.kind='ORDER_PAYMENT' THEN CASE WHEN op.method IN ('CASH','BANK') THEN op.method WHEN op.method IN ('SEPAY','VNPAY','VNPAY_QR','VNPAY_CARD','PAYPAL','SEPAY_CARD') THEN 'GATEWAY' ELSE 'UNSPECIFIED' END ELSE CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(h.data,'$.paidMethod')) IN ('CASH','BANK') THEN JSON_UNQUOTE(JSON_EXTRACT(h.data,'$.paidMethod')) WHEN JSON_UNQUOTE(JSON_EXTRACT(h.data,'$.paidMethod')) IN ('SEPAY','VNPAY','VNPAY_QR','VNPAY_CARD','PAYPAL','SEPAY_CARD') THEN 'GATEWAY' ELSE 'UNSPECIFIED' END END AS method,r.reference,r.amount,CASE WHEN r.kind='ORDER_PAYMENT' THEN o.id IS NOT NULL AND op.order_id=o.id AND op.amount=r.amount AND (cm.cart_id IS NULL OR c.id IS NOT NULL) WHEN r.kind='HOTEL_PAYMENT' THEN h.id IS NOT NULL ELSE p.id IS NOT NULL END AS consistent FROM jingo_payment_references r LEFT JOIN jingo_cart_orders cm ON r.kind='ORDER_PAYMENT' AND cm.order_id=r.entity_id LEFT JOIN jingo_carts c ON c.id=cm.cart_id LEFT JOIN jingo_orders o ON r.kind='ORDER_PAYMENT' AND o.id=r.entity_id LEFT JOIN jingo_order_payments op ON r.kind='ORDER_PAYMENT' AND op.reference_hash=r.reference_hash LEFT JOIN jingo_stay_bookings h ON r.kind='HOTEL_PAYMENT' AND h.id=r.entity_id LEFT JOIN jingo_partners p ON r.kind='PARTNER_REPAYMENT' AND p.id=r.entity_id WHERE r.kind IN ('ORDER_PAYMENT','HOTEL_PAYMENT','PARTNER_REPAYMENT') AND NOT EXISTS(SELECT 1 FROM jingo_checkout_members bm WHERE bm.kind='cartId' AND bm.entity_id=cm.cart_id) AND r.created_at>=? AND r.created_at<?";
        $refund="SELECT CONCAT('OUT:',id) AS id,root_kind AS kind,root_id AS entityId,root_code AS code,'OUT' AS direction,refunded_on AS effectiveDate,created_at AS recordedAt,JSON_UNQUOTE(JSON_EXTRACT(data,'$.method')) AS method,JSON_UNQUOTE(JSON_EXTRACT(data,'$.reference')) AS reference,amount,1 AS consistent FROM jingo_refunds WHERE root_kind IN ('ORDER','CART','BUNDLE','HOTEL','RIDE') AND refunded_on>=? AND refunded_on<=?";
        $ride="SELECT CONCAT('RIDE:',m.id) AS id,'RIDE' AS kind,b.id AS entityId,COALESCE(b.code,m.reference) AS code,'IN' AS direction,DATE(DATE_ADD(m.created_at,INTERVAL 7 HOUR)) AS effectiveDate,m.created_at AS recordedAt,'CASH' AS method,m.id AS reference,m.amount,CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paymentStatus'))='PAID' AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.cashReceipt.id'))=m.id AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.cashReceipt.shiftId'))=m.shift_id AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.cashReceipt.amount'))=m.amount AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paidAmount'))=m.amount AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paymentReference'))=m.id THEN 1 ELSE 0 END AS consistent FROM jingo_pos_cash_movements m LEFT JOIN jingo_ride_bookings b ON m.reference=b.code WHERE m.kind='IN' AND m.note='Thu tiền mặt đơn xe' AND m.created_at>=? AND m.created_at<?";
        $bundle="SELECT CONCAT('BUNDLE:',r.reference_hash) AS id,'BUNDLE' AS kind,b.id AS entityId,b.code,'IN' AS direction,DATE(DATE_ADD(r.created_at,INTERVAL 7 HOUR)) AS effectiveDate,r.created_at AS recordedAt,CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paidMethod')) IN ('CASH','BANK') THEN JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paidMethod')) WHEN JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paidMethod')) IN ('VNPAY','VNPAY_QR','VNPAY_CARD','SEPAY','SEPAY_CARD','PAYPAL') THEN 'GATEWAY' ELSE 'UNSPECIFIED' END AS method,r.reference,r.amount,CASE WHEN b.status='PAID' AND b.total=r.amount AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.reference'))=r.reference THEN 1 ELSE 0 END AS consistent FROM jingo_payment_references r LEFT JOIN jingo_checkout_bundles b ON b.id=r.entity_id WHERE r.kind='BUNDLE_PAYMENT' AND r.created_at>=? AND r.created_at<?";
        $rideOnline="SELECT CONCAT('RIDE_PAY:',r.reference_hash) AS id,'RIDE' AS kind,b.id AS entityId,b.code,'IN' AS direction,DATE(DATE_ADD(r.created_at,INTERVAL 7 HOUR)) AS effectiveDate,r.created_at AS recordedAt,CASE WHEN gr.event_id IS NOT NULL THEN 'BANK' WHEN r.reference LIKE 'SEPAY:LIVE:%' THEN 'GATEWAY' ELSE 'UNSPECIFIED' END AS method,r.reference,r.amount,CASE WHEN b.id IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paymentStatus'))='PAID' AND JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paidAmount'))=r.amount AND BINARY JSON_UNQUOTE(JSON_EXTRACT(b.data,'$.paymentReference'))=BINARY r.reference THEN 1 ELSE 0 END AS consistent FROM jingo_payment_references r LEFT JOIN jingo_ride_bookings b ON b.id=r.entity_id LEFT JOIN jingo_gateway_resolutions gr ON gr.event_id=r.reference AND gr.target_code=b.code WHERE r.kind='RIDE_PAYMENT' AND r.created_at>=? AND r.created_at<?";
        $sql=' FROM ('.$receipt.' UNION ALL '.$refund.' UNION ALL '.$ride.' UNION ALL '.$bundle.' UNION ALL '.$rideOnline.') x';$args=[$start,$end,$f['from'],$f['to'],$start,$end,$start,$end,$start,$end];$conditions=[];foreach(['kind','method','direction'] as $key)if($f[$key]!=='ALL'){$conditions[]=$key.'=?';$args[]=$f[$key];}if($f['q']!==''){$conditions[]='(LOCATE(LOWER(?),LOWER(code))>0 OR LOCATE(LOWER(?),LOWER(reference))>0)';$args[]=$f['q'];$args[]=$f['q'];}if($conditions)$sql.=' WHERE '.implode(' AND ',$conditions);
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{
            $total=(int)$this->query('SELECT COUNT(*)'.$sql,$args)->fetchColumn();if($fullLedger&&$total>10000)throw new HttpError(409,'CSV chi tiết tối đa 10.000 dòng. Thu hẹp khoảng ngày hoặc bộ lọc.');$page=min($f['page'],max(1,(int)ceil($total/25)));$offset=($page-1)*25;$summary=self::zero();$daily=[];$byKind=[];$byMethod=[];$data=[];$i=0;
            for($day=new DateTimeImmutable($f['from']);$day<=new DateTimeImmutable($f['to']);$day=$day->modify('+1 day'))$daily[$day->format('Y-m-d')]=['date'=>$day->format('Y-m-d')]+self::zero();
            $rows=$this->query('SELECT *'.$sql.' ORDER BY effectiveDate DESC,recordedAt DESC,id DESC',$args);while($r=$rows->fetch(PDO::FETCH_ASSOC)){
                if(!(bool)$r['consistent'])throw new HttpError(409,'Khoản thu thiếu hoặc lệch tham chiếu đơn. Cần đối chiếu sổ gốc.');if(!in_array($r['method'],['CASH','BANK','GATEWAY','UNSPECIFIED'],true))throw new HttpError(409,'Hình thức thu/hoàn chưa được hỗ trợ.');$date=StaySchema::date($r['effectiveDate']);if(!isset($daily[$date]))throw new HttpError(409,'Ngày giao dịch ngoài kỳ báo cáo.');$r['amount']=self::money($r['amount']);unset($r['consistent']);$byKind[$r['kind']]??=['kind'=>$r['kind']]+self::zero();$byMethod[$r['method']]??=['method'=>$r['method']]+self::zero();self::record($summary,$r['direction'],$r['amount']);self::record($daily[$date],$r['direction'],$r['amount']);self::record($byKind[$r['kind']],$r['direction'],$r['amount']);self::record($byMethod[$r['method']],$r['direction'],$r['amount']);if($fullLedger||$i>=$offset&&$i<$offset+25)$data[]=$r;$i++;
            }ksort($byKind);ksort($byMethod);$this->db->commit();return ['filters'=>array_replace($f,['page'=>$page]),'generatedAt'=>gmdate('Y-m-d\TH:i:s\Z'),'summary'=>$summary,'daily'=>array_values($daily),'byKind'=>array_values($byKind),'byMethod'=>array_values($byMethod),'data'=>$data,'total'=>$total,'page'=>$page,'pageSize'=>25];
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public static function csv(array $report,bool $ledger=false):string
    {
        $f=$report['filters'];$rows=[['Báo cáo thu hoàn','Từ',$f['from'],'Đến',$f['to'],'Loại',$f['kind'],'Hình thức',$f['method'],'Chiều',$f['direction'],'Từ khóa',$f['q']]];
        if($ledger){$rows[]=['Ngày hiệu lực GMT+7','Ghi nhận UTC','Loại','Mã đơn/CTV','Chiều','Hình thức','Tham chiếu','Tiền thu VND','Tiền hoàn VND'];foreach($report['data'] as $r)$rows[]=[$r['effectiveDate'],$r['recordedAt'],$r['kind'],$r['code'],$r['direction'],$r['method'],$r['reference'],$r['direction']==='IN'?$r['amount']:0,$r['direction']==='OUT'?$r['amount']:0];}
        else{$rows[]=['Nhóm','Ngày/Loại/Hình thức','Thực thu VND','Đã hoàn VND','Thu trừ hoàn VND','Lượt thu','Lượt hoàn'];$row=static fn($group,$key,$v)=>[$group,$key,$v['received'],$v['refunded'],$v['net'],$v['receiptCount'],$v['refundCount']];$rows[]=$row('TỔNG','',$report['summary']);foreach($report['daily'] as $d)$rows[]=$row('NGÀY',$d['date'],$d);foreach($report['byKind'] as $g)$rows[]=$row('LOẠI',$g['kind'],$g);foreach($report['byMethod'] as $g)$rows[]=$row('HÌNH THỨC',$g['method'],$g);}
        $cell=static function(mixed $v):string{$numeric=is_int($v);$v=str_replace("\0",'',(string)$v);if(!$numeric&&preg_match('/^[\s\x{FEFF}]*[=+@-]|^[\t\r\n]/u',$v))$v="'".$v;return '"'.str_replace('"','""',$v).'"';};return "\xEF\xBB\xBF".implode("\r\n",array_map(fn($r)=>implode(',',array_map($cell,$r)),$rows))."\r\n";
    }
}
